INSERT INTO `service_feedback` (`id`, `name`, `email`, `message`, `environment_rating`, `food_rating`, `staff_rating`, `overall_rating`, `photo`, `ip_address`, `location`, `status`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 'Marjon Dale L. Nina', 'marjon@gmail.com', 'The food is good and the ambiance is nice, Just very amaze on the service of the waiter highly recommend!', 5, 4.5, 5, 4.83, 'img/feedback_photos/69080ca0a064e.jpg', '127.0.0.1', 'Ashburn, Virginia, United States, ', 35, '2025-11-03 11:25:14', '2025-11-03 17:57:42', NULL),
(2, 'Gavin Josh Daguino', 'gavinjosh@gmail.com', 'The place is nice, I always go here whenever I check my students petition thesis documents.😍🤞', 4, 4, 4, 4, 'img/feedback_photos/69080d6e2403b.jpg', '127.0.0.1', 'Ashburn, Virginia, United States, ', 35, '2025-11-03 11:25:44', '2025-11-03 17:57:43', NULL),
(3, 'John Robert Nadala', 'nadala@mail.com', 'I love this place it is very close to my home, very relaxing and the staff is very approachable. Love to unwind here every day off with Mr. Mabini my best student.', 5, 5, 5, 5, 'img/feedback_photos/69080e20d919d.jpg', '127.0.0.1', 'Ashburn, Virginia, United States, ', 35, '2025-11-03 11:26:07', '2025-11-04 17:40:39', NULL),
(4, 'haha', 'haha@mail.com', 'test', 2, 2, 2.5, 2.17, NULL, '2400:d1e0:8200:1c27:f09b:ce8:7ec8:2c24', 'General Trias, Calabarzon, Philippines, ', 34, '2025-11-03 12:23:43', '2025-11-14 21:55:45', NULL),
(5, 'Nat', 'nathanielvasquez329@gmail.com', 'message', 4, 4.5, 5, 4.5, 'img/feedback_photos/690860249b017.jpg', '2400:d1e0:8200:1c27:f09b:ce8:7ec8:2c24', 'General Trias, Calabarzon, Philippines, ', 34, '2025-11-03 15:56:20', '2025-11-04 17:20:24', NULL),
(6, 'testing', 'test@mail.com', 'testinggggggggggggggggggggggggggggggggggg', 3, 3.5, 2.5, 3, 'img/feedback_photos/6909cb1b7966d.jpg', '2400:d1e0:8200:1c27:7d58:8e84:70d5:31c6', 'General Trias, Calabarzon, Philippines, ', 34, '2025-11-04 17:44:59', '2025-11-04 17:45:32', NULL),
(7, 'test', 'test@mail.com', 'test', 5, 4, 3.5, 4.17, 'img/feedback_photos/6909fb020ef82.jpg', '2400:d1e0:8200:1c27:7d58:8e84:70d5:31c6', 'General Trias, Calabarzon, Philippines, ', 34, '2025-11-04 21:09:22', '2025-11-14 21:50:48', NULL),
(8, 'hehe', 'test@mail.com', 'Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do eiusmod tempor incididunt ut labore et dolore magna aliqua.\r\nLorem ipsum dolor sit amet, consectetur adipiscing elit, sed do eiusmod tempor incididunt ut labore et dolore magna aliqua.\r\nLorem', 5, 4.5, 3.5, 4.33, 'img/feedback_photos/6909fb519285f.jpg', '2400:d1e0:8200:1c27:7d58:8e84:70d5:31c6', 'General Trias, Calabarzon, Philippines, ', 35, '2025-11-04 21:10:41', '2025-11-04 21:11:17', NULL),
(10, 'Cedric John Pat Luwi', 'cedpatmarcoluwi.com.ph@ncst.com', 'The pasta was perfectly cooked — al dente and flavorful! The sauce was rich and creamy, definitely one of the best I\'ve had.', 5, 5, 5, 5, 'img/feedback_photos/690a1ba7a330f.jpg', '123.253.50.230', 'Dasmariñas, Calabarzon, Philippines, ', 35, '2025-11-04 23:28:39', '2025-11-04 23:30:21', NULL),
(11, 'Charles', 'charleslouiealvaran@gmail.com', 'magaling mag serve yung staff pati yung food', 4.5, 4.5, 4.5, 4.5, 'img/feedback_photos/690a1c2d05225.jpg', '2001:fd8:d22b:b400:2df3:7715:2e0d:1b04', 'Makati City, Metro Manila, Philippines, ', 34, '2025-11-04 23:30:53', '2025-11-10 19:33:22', NULL),
(13, 'Cedric Kyle Belisario', 'cedricbelisario@gmail.com', 'The pasta was perfectly cooked — al dente and flavorful! The sauce was rich and creamy, definitely one of the best I\'ve had.', 5, 3, 5, 4.33, 'img/feedback_photos/6912ef8022189.jpg', '175.176.49.71', 'Cabuyao, Calabarzon, Philippines, ', 35, '2025-11-11 16:10:40', '2025-11-14 21:56:05', NULL),
